public static boolean isBase64Region(byte[] data, int offset, int length) {
    final int end = offset + length;
    for (int i = offset; i < end; i++) {
        final byte octet = data[i];
        if (octet <= ' ') {
            if (octet != ' ' && octet != '\t' && octet != '\n' && octet != '\r') {
                return false;
            }
            continue;
        }
        if (!Base64.isBase64(octet)) {
            return false;
        }
    }
    return true;
}


